                exposed_actions_count = group_action_count - suppressed_actions_count
                if not exposed_actions_count:
                    continue

                if not group.required:
                    if start in inserts:
                        inserts[start] += ' ['
                    else:
                        inserts[start] = '['
                    if end in inserts:
                        inserts[end] += ']'
                    else:
                        inserts[end] = ']'
                elif exposed_actions_count > 1:
                    if start in inserts:
                        inserts[start] += ' ('
                    else:
                        inserts[start] = '('
                    if end in inserts:
                        inserts[end] += ')'
                    else:
                        inserts[end] = ')'
