                        inserts[end] = ']'
                elif exposed_actions_count > 1:
                    if start in inserts:
                        inserts[start] += ' ('
                    else:
                        inserts[start] = '('
                    if end in inserts:
                        inserts[end] += ')'
                    else:
                        inserts[end] = ')'
